-- Tables the m425 core reads for Haradon characters
-- Generated by NetCoreClient/tools/M425Patch from the 425 tables. Do not edit; re-run tools/build-m425.sh.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `m425_class` (
  `class` tinyint unsigned NOT NULL COMMENT 'WoW class the 425 class plays as',
  `class_425` tinyint unsigned NOT NULL,
  `power_type` tinyint unsigned NOT NULL COMMENT 'Powers enum: 0 mana, 1 rage, 3 energy',
  `max_power` smallint unsigned NOT NULL DEFAULT 0 COMMENT 'fixed maximum for rage/energy, 0 = from m425_classlevelstats',
  `start_power` smallint unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`class`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='m425: Haradon class rules';
CREATE TABLE IF NOT EXISTS `m425_classlevelstats` (
  `class` tinyint unsigned NOT NULL,
  `level` tinyint unsigned NOT NULL,
  `basehp` smallint unsigned NOT NULL,
  `basemana` smallint unsigned NOT NULL,
  PRIMARY KEY (`class`, `level`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='m425: Haradon base HP/mana (replaces player_classlevelstats)';
CREATE TABLE IF NOT EXISTS `m425_xp_for_level` (
  `lvl` tinyint unsigned NOT NULL,
  `xp_for_next_level` int unsigned NOT NULL,
  PRIMARY KEY (`lvl`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='m425: Haradon XP curve (replaces player_xp_for_level)';
CREATE TABLE IF NOT EXISTS `m425_appearance` (
  `race` tinyint unsigned NOT NULL,
  `gender` tinyint unsigned NOT NULL,
  `skin` tinyint unsigned NOT NULL,
  `face` tinyint unsigned NOT NULL,
  `hair_style` tinyint unsigned NOT NULL,
  `hair_color` tinyint unsigned NOT NULL,
  `facial_hair` tinyint unsigned NOT NULL,
  PRIMARY KEY (`race`, `gender`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='m425: highest appearance option per race and gender (1-based, 0 also allowed)';
DELETE FROM `m425_class` WHERE 1;
